with filtered_order_items as (select * from order_items where product_id is null and quantity <= 6 and product_id in (12, 19, 30, 37)), OrderIdSummary as (select order_id, case when quantity >= 7 then 'high' when quantity >= 3 then 'mid' else 'low' end quantity_bucket, min(quantity) min_quantity from filtered_order_items group by order_id, case when quantity >= 7 then 'high' when quantity >= 3 then 'mid' else 'low' end) select order_id, quantity_bucket, min_quantity from OrderIdSummary order by quantity_bucket desc
